insert into basket_division (
    season_id, platform_code, game_mode, division_name, registration_mode, format_type, format_template_id, format_snapshot_id, max_team_count, max_person_count, lineup_min_count, lineup_max_count, registration_start_time, registration_end_time, match_start_time, match_end_time, division_status, sort_order, create_time, update_time, is_delete
) values (
    #{seasonId}, #{platformCode}, #{gameMode}, #{divisionName}, #{registrationMode}, #{formatType}, #{formatTemplateId}, #{formatSnapshotId}, #{maxTeamCount}, #{maxPersonCount}, #{lineupMinCount}, #{lineupMaxCount}, #{registrationStartTime}, #{registrationEndTime}, #{matchStartTime}, #{matchEndTime}, #{divisionStatus}, #{sortOrder}, #{createTime}, #{updateTime}, #{isDelete}
)
